import{_ as r,c as t,o as e,ag as i}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"小程式來源","description":"nPlyr 的小程式與規則來源來自哪裡，以及如何新增你自己的來源。","frontmatter":{"title":"小程式來源","description":"nPlyr 的小程式與規則來源來自哪裡，以及如何新增你自己的來源。","layout":"doc"},"headers":[],"relativePath":"zh-TW/guide/miniapp-sources.md","filePath":"zh-TW/guide/miniapp-sources.md","lastUpdated":1791311600000}'),o={name:"zh-TW/guide/miniapp-sources.md"};function n(l,a,s,d,p,c){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="小程式來源" tabindex="-1">小程式來源 <a class="header-anchor" href="#小程式來源" aria-label="Permalink to &quot;小程式來源&quot;">​</a></h1><p>本頁屬於<strong>小程式</strong>指南章節——即 nPlyr 可以匯入的社群小程式與規則來源目錄。nPlyr <strong>不</strong>隨附固定的影片來源清單；相反，來源由你自行提供，應用程式內的管理器負責匯入。</p><h2 id="來源來自哪裡" tabindex="-1">來源來自哪裡 <a class="header-anchor" href="#來源來自哪裡" aria-label="Permalink to &quot;來源來自哪裡&quot;">​</a></h2><ul><li><strong>hikerView 生態。</strong> nPlyr 與 Android 應用程式所用的同一批分享文字和 JSON 相容，因此現有社群規則可直接匯入。</li><li><strong>雲端分享。</strong> nPlyr 支援雲端後端 <strong>TextDB</strong>（雲2）、<code>cmd.im</code>（302 重新導向，雲5）與 <strong>pasteme</strong>（雲6），因此託管在那裡的規則可以一步訂閱。</li><li><strong>你自己的。</strong> 編寫或改編一條規則並匯入——請先參閱<a href="/zh-TW/guide/miniapps.html">小程式概覽</a>與<a href="/zh-TW/guide/miniapp-compatibility.html">相容性</a>邊界。</li></ul><h2 id="新增來源" tabindex="-1">新增來源 <a class="header-anchor" href="#新增來源" aria-label="Permalink to &quot;新增來源&quot;">​</a></h2><ol><li>在 nPlyr 中打開<strong>小程式</strong>（macOS 上是管理器視窗，iOS 上是一個頁面）。</li><li>選擇<strong>新增</strong>，貼上分享文字 / JSON，或選擇一個雲端來源進行訂閱。</li><li>該程式會出現在首頁頂列——拖拽以重新排列。</li></ol><p>免費層級限制你一次可保留的匯入程式數量；一次性解鎖會移除該限制。</p><h2 id="相容性是關鍵" tabindex="-1">相容性是關鍵 <a class="header-anchor" href="#相容性是關鍵" aria-label="Permalink to &quot;相容性是關鍵&quot;">​</a></h2><p>並非每一條 Android 規則都在 nPlyr 上完全一致地執行。nPlyr 的引擎是 <strong>JavaScriptCore</strong>，而非 Java/Rhino，並且只模擬了經過篩選的 Java API 子集。在依賴某個來源之前，請查閱<a href="/zh-TW/guide/miniapp-compatibility.html">相容性</a>頁面，並回報任何失敗的規則（附上規則名稱及其失敗的步驟）。</p><blockquote><p>你在此瀏覽的目錄由社群維護。nPlyr 並非第三方小程式的作者，也不為其內容背書——只安裝你信任的來源。</p></blockquote>',10)])])}const g=r(o,[["render",n]]);export{m as __pageData,g as default};
